-- Replace :group_id, :cycle_id and :member_id with the selected statement IDs.
SELECT COUNT(*) eligible_meetings,COUNT(*) FILTER (WHERE ma.attendance_status='PRESENT') present,COUNT(*) FILTER (WHERE ma.attendance_status='ABSENT') absent,COUNT(*) FILTER (WHERE ma.attendance_status='LATE') late,COUNT(*) FILTER (WHERE ma.attendance_status='EXCUSED') excused
FROM cycle_memberships cm JOIN vsla_meetings vm ON vm.group_id=cm.group_id AND vm.cycle_id=cm.cycle_id AND vm.status<>'CANCELLED' AND cm.participation_start_date<=vm.meeting_date AND (cm.participation_end_date IS NULL OR cm.participation_end_date>=vm.meeting_date) LEFT JOIN meeting_attendance ma ON ma.meeting_id=vm.id AND ma.member_id=cm.member_id WHERE cm.group_id=:group_id AND cm.cycle_id=:cycle_id AND cm.member_id=:member_id;
SELECT COALESCE(SUM(CASE transaction_kind WHEN 'PURCHASE' THEN amount WHEN 'REVERSAL' THEN -amount ELSE 0 END),0) net_savings FROM savings_transactions WHERE group_id=:group_id AND cycle_id=:cycle_id AND member_id=:member_id;
SELECT COALESCE(SUM(CASE transaction_kind WHEN 'CONTRIBUTION' THEN amount WHEN 'REVERSAL' THEN -amount ELSE 0 END),0) net_social_fund_contributions FROM social_fund_transactions WHERE group_id=:group_id AND cycle_id=:cycle_id AND member_id=:member_id;
SELECT COALESCE(SUM(CASE transaction_kind WHEN 'FINE' THEN amount WHEN 'REVERSAL' THEN -amount ELSE 0 END),0) fines_collected FROM fine_transactions WHERE group_id=:group_id AND cycle_id=:cycle_id AND member_id=:member_id;
SELECT COALESCE(SUM(CASE transaction_kind WHEN 'PAYMENT' THEN payment_amount WHEN 'REVERSAL' THEN -payment_amount ELSE 0 END),0) loan_repayments FROM loan_repayments WHERE group_id=:group_id AND cycle_id=:cycle_id AND member_id=:member_id;
SELECT cs.status,e.final_entitlement,COALESCE(SUM(CASE p.transaction_kind WHEN 'PAYOUT' THEN p.amount ELSE -p.amount END),0) net_paid FROM cycle_shareouts cs JOIN cycle_shareout_entitlements e ON e.shareout_id=cs.id AND e.member_id=:member_id LEFT JOIN shareout_payouts p ON p.entitlement_id=e.id WHERE cs.group_id=:group_id AND cs.cycle_id=:cycle_id GROUP BY cs.status,e.final_entitlement ORDER BY cs.status;
